  FROM item i WHERE i.id = {{node:code_node_FLgate.data.mat}}"},"response_json":[{"key":"mageyo54","name":"uom","title":"uom","description":"","bsonType":"string","isExpand":false,"children":[]},{"key":"e8dxcya4","name":"open_qty","title":"open_qty","description":"","bsonType":"number","isExpand":false,"children":[]},{"key":"cpbkt767","name":"docs","title":"docs","description":"","bsonType":"string","isExpand":false,"children":[]}],"params":{},"result_mode":"many","nodeName":"IA floor: open Item Assembly holds on this row","name":"IA floor: open Item Assembly holds on this row","tableId":"1935880014687440897","table_id":{"source":"On Reserved Goods Delivery:Table:1935880014687440897","rules":{"collectionId":"1935880014687440897","list":[]}}}},{"id":"code_node_FLcheck","type":"code-node","properties":{"language":"javascript","code":"","timeout":30000,"isValidator":true,"nodeName":"IA floor: would this subtract cut into the IA holds?","name":"IA floor: would this subtract cut into the IA holds?","script":{"type":"javascript","code":"// held = the open IA hold rows in base units (each row's unit converted as code_node_wBfvXM2G converts); the bucket is the
// one code_node_DUBS9GZF checked (the batch row when batched)
const q8 = (v) => Number((parseFloat(v) || 0).toFixed(8));
const itemData = {{node:code_node_TC1cqaOy.data.itemData}} || {};
const conv = Array.isArray(itemData.table_uom_conversion) ? itemData.table_uom_conversion : [];
const raw = [{{node:sql_node_FLholds.data}}][0];
const rows = Array.isArray(raw) ? raw : raw ? [raw] : [];
let held = 0;
const docs = [];
for (const r of rows) {
  const c = conv.find((x) => String(x.alt_uom_id) === String(r.uom));
  held = q8(held + q8(r.open_qty) * (c ? Number(c.base_qty) || 1 : 1));
  if (r.docs) docs.push(r.docs);
}
const reservedNow = q8({{node:code_node_DUBS9GZF.data.currentCategoryQty}});
const after = q8(reservedNow - q8({{node:code_node_wBfvXM2G.data.baseQty}}));
const refuse = held > 0 && after < held;
return {
  refuse: refuse ? "YES" : "NO", held: held, after: after,
